//! Generates the TypeScript types of the protocol (`web/src/protocol/`) and fails when the
//! checked-in files differ. To update them after changing the protocol:
//!
//!     UPDATE_TS_BINDINGS=1 cargo test --release -p treachery-protocol --test ts_bindings
//!
//! The game view's types are generated by the view crate into `web/src/generated/`. Files for
//! those types are left out here, and the protocol's files import them from there, as they do
//! the enum unions of `generated/enums.ts`.

use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

use treachery_protocol::{Call, CallReplies, Notification, Request, ServerMessage};
use ts_rs::{Config, TS};

fn web_src() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../web/src")
}

fn read_dir(dir: &Path) -> BTreeMap<String, String> {
    let Ok(entries) = std::fs::read_dir(dir) else { return BTreeMap::new() };
    entries
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().is_some_and(|e| e == "ts"))
        .map(|p| (p.file_name().unwrap().to_string_lossy().to_string(), std::fs::read_to_string(&p).unwrap()))
        .collect()
}

/// The names `generated/enums.ts` exports.
fn enum_names(enums_ts: &str) -> Vec<String> {
    enums_ts.lines().filter_map(|l| l.strip_prefix("export type ")).filter_map(|l| l.split_whitespace().next()).map(str::to_string).collect()
}

fn contains_word(text: &str, word: &str) -> bool {
    text.match_indices(word).any(|(i, _)| {
        let before = text[..i].chars().last();
        let after = text[i + word.len()..].chars().next();
        let ident = |c: Option<char>| c.is_some_and(|c| c.is_alphanumeric() || c == '_' || c == '"');
        !ident(before) && !ident(after)
    })
}

fn generate() -> BTreeMap<String, String> {
    let view_files: BTreeSet<String> = read_dir(&web_src().join("generated")).into_keys().collect();
    assert!(view_files.contains("GameView.ts"), "web/src/generated has the view's types");
    let enums = enum_names(&std::fs::read_to_string(web_src().join("generated/enums.ts")).unwrap());

    let dir = std::env::temp_dir().join(format!("treachery-protocol-ts-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    let cfg = Config::new().with_out_dir(&dir);
    Call::export_all(&cfg).unwrap();
    Request::export_all(&cfg).unwrap();
    ServerMessage::export_all(&cfg).unwrap();
    Notification::export_all(&cfg).unwrap();
    CallReplies::export_all(&cfg).unwrap();

    let mut files = BTreeMap::new();
    for entry in std::fs::read_dir(&dir).unwrap() {
        let path = entry.unwrap().path();
        let name = path.file_name().unwrap().to_string_lossy().to_string();
        if view_files.contains(&name) {
            continue;
        }
        let mut text = std::fs::read_to_string(&path).unwrap();
        for view_file in &view_files {
            let module = view_file.trim_end_matches(".ts");
            text = text.replace(&format!("from \"./{module}\";"), &format!("from \"../generated/{module}\";"));
        }
        // Only code lines: doc comments mention enum names too.
        let code: String = text.lines().filter(|l| !l.trim_start().starts_with('*') && !l.trim_start().starts_with("/*")).collect::<Vec<_>>().join("\n");
        let used: Vec<&str> = enums.iter().map(String::as_str).filter(|n| contains_word(&code, n)).collect();
        if !used.is_empty() {
            text = format!("import type {{ {} }} from \"../generated/enums\";\n{text}", used.join(", "));
        }
        let events: Vec<&str> = ["Event", "GameSettings"].into_iter().filter(|n| contains_word(&code, n)).collect();
        if !events.is_empty() {
            text = format!("import type {{ {} }} from \"../generated/Event\";\n{text}", events.join(", "));
        }
        files.insert(name, text);
    }
    std::fs::remove_dir_all(&dir).unwrap();
    files
}

/// `web/src/generated/Event.ts`: every event type, the `Event` union and the types they use.
fn events_ts() -> String {
    use treachery_engine::events::wire::ForceEntry;
    use treachery_engine::events::{Event, HistoryEntry};
    use treachery_engine::game::GameSettings;
    use treachery_engine::enumerations::ShipmentPermission;
    let cfg = Config::new();
    let enums = enum_names(&std::fs::read_to_string(web_src().join("generated/enums.ts")).unwrap());
    let mut decls: Vec<String> = vec![ForceEntry::decl(&cfg), ShipmentPermission::decl(&cfg), GameSettings::decl(&cfg), HistoryEntry::decl(&cfg)];
    decls.extend(Event::typescript_structs(&cfg).into_iter().map(|(_, d)| d));
    let body: String = decls.iter().map(|d| format!("export {d}\n\n")).collect::<String>() + &Event::typescript_union();
    // ShipmentPermission is also an enum union of its flag names, for old drafts; Event.ts declares the struct.
    let used: Vec<&str> = enums.iter().map(String::as_str).filter(|n| *n != "ShipmentPermission" && contains_word(&body, n)).collect();
    format!(
        "// Generated by rust/protocol/tests/ts_bindings.rs from the engine's events. Do not edit.\n// The wire format is in rewrite-plan.md, \"Wire format\", and engine/src/events/wire.rs.\n\nimport type {{ {} }} from \"./enums\";\n\n{body}",
        used.join(", ")
    )
}

#[test]
fn event_typescript_is_current() {
    let path = web_src().join("generated/Event.ts");
    let text = events_ts();
    if std::env::var("UPDATE_TS_BINDINGS").is_ok() {
        std::fs::write(&path, &text).unwrap();
        return;
    }
    assert_eq!(std::fs::read_to_string(&path).ok().as_deref(), Some(text.as_str()), "web/src/generated/Event.ts is out of date. Run: UPDATE_TS_BINDINGS=1 cargo test --release -p treachery-protocol --test ts_bindings");
}

#[test]
fn typescript_bindings_are_current() {
    let generated = generate();
    let dir = web_src().join("protocol");
    if std::env::var("UPDATE_TS_BINDINGS").is_ok() {
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        for (name, text) in &generated {
            std::fs::write(dir.join(name), text).unwrap();
        }
        return;
    }
    let existing = read_dir(&dir);
    let stale: Vec<&String> = generated.keys().filter(|k| existing.get(*k) != generated.get(*k)).chain(existing.keys().filter(|k| !generated.contains_key(*k))).collect();
    assert!(stale.is_empty(), "web/src/protocol is out of date ({stale:?}). Run: UPDATE_TS_BINDINGS=1 cargo test --release -p treachery-protocol --test ts_bindings");
}
